import{_ as t,o as n,c as o,a2 as s}from"./chunks/framework.DpXDHk3d.js";const g=JSON.parse('{"title":"7.1 变压器的工作原理","description":"","frontmatter":{},"headers":[],"relativePath":"electrician/low-voltage-electrician/07-chapter-7-bian-ya-qi/7-1-bian-ya-qi-de-gong-zuo-yuan-li.md","filePath":"electrician/low-voltage-electrician/07-chapter-7-bian-ya-qi/7-1-bian-ya-qi-de-gong-zuo-yuan-li.md","lastUpdated":1793095197000}'),i={name:"electrician/low-voltage-electrician/07-chapter-7-bian-ya-qi/7-1-bian-ya-qi-de-gong-zuo-yuan-li.md"};function e(l,a,r,c,p,d){return n(),o("div",null,[...a[0]||(a[0]=[s(`<h1 id="_7-1-变压器的工作原理" tabindex="-1">7.1 变压器的工作原理 <a class="header-anchor" href="#_7-1-变压器的工作原理" aria-label="Permalink to &quot;7.1 变压器的工作原理&quot;">​</a></h1><h2 id="本节导读" tabindex="-1">本节导读 <a class="header-anchor" href="#本节导读" aria-label="Permalink to &quot;本节导读&quot;">​</a></h2><p>变压器是电力的&quot;翻译官&quot;——把电压升高或降低,却不改变电能总量。它是靠 2.6 节讲的<strong>电磁感应(互感)<strong>原理工作的。这一节讲核心公式</strong>变比</strong>,必须会算。</p><h2 id="一、变压器是干什么的" tabindex="-1">一、变压器是干什么的 <a class="header-anchor" href="#一、变压器是干什么的" aria-label="Permalink to &quot;一、变压器是干什么的&quot;">​</a></h2><p><strong>变压器</strong>:利用电磁感应原理,把一种交流电压变成另一种交流电压的电气设备。</p><ul><li><strong>升压变压器</strong>:电压升高(用于输电);</li><li><strong>降压变压器</strong>:电压降低(用于配电,如 10 kV → 0.4 kV);</li><li><strong>隔离变压器</strong>:电压不变,只做电气隔离。</li></ul><h2 id="二、基本结构-两个绕组-一个铁芯" tabindex="-1">二、基本结构:两个绕组 + 一个铁芯 <a class="header-anchor" href="#二、基本结构-两个绕组-一个铁芯" aria-label="Permalink to &quot;二、基本结构:两个绕组 + 一个铁芯&quot;">​</a></h2><p>变压器由<strong>一次绕组(初级)、二次绕组(次级)<strong>和</strong>铁芯</strong>组成:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  一次绕组(接电源)        铁芯(导磁)      二次绕组(接负载)</span></span>
<span class="line"><span>  ┌─────────┐       ┌──────────┐       ┌─────────┐</span></span>
<span class="line"><span>  │  N1 匝  │ ══════╪  ════════╪ ════ ═│  N2 匝  │</span></span>
<span class="line"><span>  └─────────┘       └──────────┘       └─────────┘</span></span>
<span class="line"><span>      U1、I1                              U2、I2</span></span></code></pre></div><ul><li><strong>一次绕组</strong>接交流电源,匝数 N1;</li><li><strong>二次绕组</strong>接负载,匝数 N2;</li><li>铁芯把磁场集中起来,提高效率。</li></ul><h2 id="三、工作原理-互感-核心" tabindex="-1">三、工作原理:互感(核心!) <a class="header-anchor" href="#三、工作原理-互感-核心" aria-label="Permalink to &quot;三、工作原理:互感(核心!)&quot;">​</a></h2><ol><li>一次绕组接交流电源 → 一次侧电流<strong>交变</strong> → 铁芯中磁通<strong>交变</strong>;</li><li>交变磁通<strong>同时穿过</strong>二次绕组 → 二次绕组中感应出电动势(互感);</li><li>二次绕组接上负载 → 有电流输出。</li></ol><blockquote><p>⚠️ 关键:<strong>磁通必须&quot;变&quot;才能生电</strong>。交流电流方向不断变化,磁通不断变化,才能持续感应;<strong>直流电流不变化,磁通不变,不能感应出电压</strong>——所以变压器只能变交流,不能变直流。</p></blockquote><h2 id="四、变比公式-必背、必算" tabindex="-1">四、变比公式(必背、必算) <a class="header-anchor" href="#四、变比公式-必背、必算" aria-label="Permalink to &quot;四、变比公式(必背、必算)&quot;">​</a></h2><h3 id="电压与匝数成正比" tabindex="-1">电压与匝数成正比 <a class="header-anchor" href="#电压与匝数成正比" aria-label="Permalink to &quot;电压与匝数成正比&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>U1 / U2 = N1 / N2</span></span></code></pre></div><p>电压之比等于匝数之比。二次匝数多于一次 → 升压;少于一次 → 降压。</p><h3 id="电流与匝数成反比" tabindex="-1">电流与匝数成反比 <a class="header-anchor" href="#电流与匝数成反比" aria-label="Permalink to &quot;电流与匝数成反比&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>I1 / I2 = N2 / N1</span></span></code></pre></div><p>电流之比等于匝数的<strong>反比</strong>。也就是说:<strong>电压升高的同时电流变小,电压降低的同时电流变大</strong>。</p><h3 id="功率守恒-理想情况" tabindex="-1">功率守恒(理想情况) <a class="header-anchor" href="#功率守恒-理想情况" aria-label="Permalink to &quot;功率守恒(理想情况)&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>U1 × I1 ≈ U2 × I2</span></span></code></pre></div><blockquote><p>💡 通俗理解:<strong>变压器是&quot;不增不减电能&quot;的转换器</strong>——它把&quot;高电压小电流&quot;变成&quot;低电压大电流&quot;,或反过来,能量总量基本不变。就像用齿轮换速:转速变慢就力量变大。</p></blockquote><h2 id="五、计算例题" tabindex="-1">五、计算例题 <a class="header-anchor" href="#五、计算例题" aria-label="Permalink to &quot;五、计算例题&quot;">​</a></h2><p><strong>例题</strong>:一台降压变压器,一次侧电压 380 V,一次绕组匝数 1000 匝,二次绕组匝数 200 匝。求二次侧电压。</p><p><strong>解</strong>:<code>U1/U2 = N1/N2</code><code>380/U2 = 1000/200</code><code>U2 = 380 × 200/1000 = 76 V</code></p><h2 id="六、考点提示" tabindex="-1">六、考点提示 <a class="header-anchor" href="#六、考点提示" aria-label="Permalink to &quot;六、考点提示&quot;">​</a></h2><ul><li>✅ <strong>U1/U2 = N1/N2</strong>(电压与匝数成正比)。</li><li>✅ <strong>I1/I2 = N2/N1</strong>(电流与匝数成反比)。</li><li>✅ 变压器只能变<strong>交流</strong>,不能变直流。</li><li>✅ 功率基本守恒:U1·I1 ≈ U2·I2。</li><li>⚠️ 易混点:电压跟匝数<strong>正比</strong>,电流跟匝数<strong>反比</strong>,别记反。</li></ul><h2 id="七、本节小结" tabindex="-1">七、本节小结 <a class="header-anchor" href="#七、本节小结" aria-label="Permalink to &quot;七、本节小结&quot;">​</a></h2><ul><li>变压器靠互感原理,靠&quot;交变磁通&quot;在二次绕组感应电压。</li><li>变比公式:电压正比于匝数、电流反比于匝数。</li><li>只能变换交流,不能变换直流。</li></ul><h2 id="八、自测练习" tabindex="-1">八、自测练习 <a class="header-anchor" href="#八、自测练习" aria-label="Permalink to &quot;八、自测练习&quot;">​</a></h2><ol><li>(判断)变压器是利用电磁感应原理工作的。( )</li><li>(单选)变压器的电压与匝数的关系是()。 A. 成正比　B. 成反比　C. 无关　D. 平方关系</li><li>(判断)变压器可以变换直流电压。( )</li><li>(计算)变压器一次电压 220 V,一次绕组 500 匝,二次绕组 100 匝,求二次电压。</li><li>(判断)升压变压器的二次电流比一次电流小。( )</li></ol><details><summary>参考答案(点击展开)</summary><ol><li><strong>√</strong>。靠电磁感应(互感)原理。</li><li><strong>A</strong>。U1/U2 = N1/N2,电压与匝数成正比。</li><li><strong>×</strong>。直流不变化,不能感应,变压器只能变交流。</li><li>U2 = 220 × 100/500 = <strong>44 V</strong>。</li><li><strong>√</strong>。电压升高的同时电流减小(功率守恒),升压变压器的二次电流小于一次电流。</li></ol></details>`,33)])])}const u=t(i,[["render",e]]);export{g as __pageData,u as default};
